import React from 'react';
import { useParams, Link } from 'react-router-dom';
import './CursoDetalle.css'; // Estilos específicos para la página de detalle del curso

const CursoDetalle = () => {
  const { id } = useParams(); // Obtener el ID del curso desde la URL

  // Aquí puedes agregar la lógica para obtener los detalles del curso desde la base de datos
  const curso = {
    id,
    nombre: id === '1' ? 'Curso de React' : 'Curso de JavaScript',
    descripcion: id === '1' ? 'Aprende a desarrollar aplicaciones web con React.' : 'Domina el lenguaje de programación JavaScript.',
    precio: id === '1' ? 100 : 80,  // Ejemplo de precio
  };

  return (
    <div className="curso-detalle">
      {/* Información del curso */}
      <h1>{curso.nombre}</h1>
      <p>{curso.descripcion}</p>
      <p><strong>Precio: ${curso.precio}</strong></p>

      {/* Botón de compra */}
      <div className="boton-compra">
        <Link to={`/pago/${curso.id}`} className="btn-compra">Comprar ahora</Link>
      </div>

      {/* Formulario de inscripción */}
      <div className="formulario-inscripcion">
        <h3>Inscríbete para recibir novedades</h3>
        <form>
          <input type="text" placeholder="Tu nombre" required />
          <input type="email" placeholder="Tu correo electrónico" required />
          <button type="submit" className="btn-inscripcion">Inscribirse</button>
        </form>
      </div>
    </div>
  );
};

export default CursoDetalle;
